const { theme } = useSiteTheme()
watch([theme, isPrivateView], ([currentTheme, privateView]) => {
  if (!import.meta.client) return
  const isNight = currentTheme === 'night' && privateView
  document.body.style.backgroundColor = isNight ? '#17191d' : ''
  document.body.style.color = isNight ? '#e4e5e7' : ''
  document.documentElement.style.colorScheme = isNight ? 'dark' : 'light'
}, { immediate: true })
</script>

