.home-layout{display:grid;width:min(1692px,calc(100% - 32px));grid-template-columns:240px minmax(0,1180px) 240px;gap:16px;align-items:start;margin:0 auto}
.home-layout>.main-content{width:100%;min-width:0;margin:0}
.home-news-rail{position:sticky;top:62px;display:flex;max-height:calc(100vh - 72px);flex-direction:column;gap:8px;align-self:start;overflow-y:auto;margin-top:26px;padding:10px;border:1px solid #e6e9e9;border-radius:8px;background:#fff;box-shadow:0 5px 18px #18212b12}
.home-news-rail{scrollbar-width:none}
.home-news-rail::-webkit-scrollbar{display:none}
.home-news-rail h2{margin:0 0 2px;padding-bottom:7px;border-bottom:2px solid #bb1919;color:#26383d;font-size:12px}
.rail-news-card{position:relative;display:block;flex:none;overflow:hidden;padding:6px;border:1px solid #edf0f0;border-radius:5px;background:#fbfcfc}
.rail-news-card img{display:block;width:100%;height:75px;margin-bottom:5px;border-radius:3px;object-fit:cover}
.rail-news-card .tag{display:block;margin-bottom:4px;font-size:7px}
.rail-news-card b{display:-webkit-box;overflow:hidden;color:#29363b;font-size:10px;line-height:1.3;-webkit-box-orient:vertical;-webkit-line-clamp:3}
.rail-rank{position:absolute;top:10px;left:10px;z-index:1;padding:3px 5px;border-radius:3px;background:#bb1919;color:#fff;font-size:9px;font-weight:800}
@media(min-width:1101px){.rail-news-card{transition:transform .3s ease,box-shadow .3s ease,border-color .3s ease;animation:rail-card-enter .7s cubic-bezier(.2,.75,.25,1) both,rail-card-bob 3s ease-in-out infinite}.rail-news-card:nth-child(2){animation-delay:.08s}.rail-news-card:nth-child(3){animation-delay:.16s}.rail-news-card:nth-child(4){animation-delay:.24s}.rail-news-card:nth-child(5){animation-delay:.32s}.rail-news-card:nth-child(6){animation-delay:.4s}.most-read-rail .rail-news-card:hover{transform:translateX(4px);border-color:#bb1919;box-shadow:0 0 0 1px #bb191933,0 6px 14px #18212b18}.politics-rail .rail-news-card:hover{transform:translateX(-4px);border-color:#bb1919;box-shadow:0 0 0 1px #bb191933,0 6px 14px #18212b18}.rail-rank{animation:rail-rank-glow 1.8s ease-in-out infinite}}
@keyframes rail-card-enter{from{opacity:0}to{opacity:1}}
